<?php declare(strict_types=1); ?>
<section class="section"><div class="container-narrow"><div class="section-heading"><p class="eyebrow">Member events</p><h1>My event registrations</h1><p>Register for member-only events from their event page.</p></div><?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?><?php if($registrations===[]):?><div class="empty-state" role="status"><p>No event registrations yet. <a href="/events">Browse events</a>.</p></div><?php else:?><?php foreach($registrations as $registration):?><article class="admin-panel"><span class="status-pill"><?= $e(ucwords($registration['status'])) ?></span><h2><a href="/events/<?= rawurlencode($registration['slug']) ?>"><?= $e($registration['title']) ?></a></h2><p><?= $e($registration['event_date']) ?> · <?= $e($registration['registration_reference']) ?></p></article><?php endforeach;?><?php endif;?></div></section>
<?php if(is_array($selectedEvent??null)):?><section class="section"><div class="container-narrow"><h2>Register for <?= $e($selectedEvent['title']) ?></h2><form method="post" action="/account/events/<?= rawurlencode($selectedEvent['public_id']) ?>/register" class="form-grid"><?= $csrf->field() ?><label>Name<input name="name" maxlength="200" required></label><label>Phone<input name="phone" maxlength="40"></label><button class="btn btn-navy" type="submit">Confirm member registration</button></form></div></section><?php endif;?>
